#!/usr/bin/env bash
set -euo pipefail
if [[ ! -f pubspec.yaml || ! -d android || ! -d .git ]]; then
  echo 'Run this script from your existing MaxPlayer repository root.' >&2
  exit 1
fi
python3 - <<'HYPER_FILES'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/README.md': '',
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/playlist.dart': '',
'desktop/hyper_player/pubspec.yaml': '',
'desktop/hyper_player/test/playlist_test.dart': '',
'.github/workflows/windows-preview.yml': '',
}
for name in files:
    if Path(name).exists():
        raise SystemExit('Refusing to overwrite existing file: ' + name)
for name, data in files.items():
    path = Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(data))
print('Windows preview source and CI added. Android files unchanged.')
HYPER_FILES
